-- Found by SQLite's TCL suite (aggnested, window3, select9, timediff1):
-- * group_concat / string_agg with a per-row separator expression;
-- * window functions over GROUP BY / aggregate queries, and window calls
--   in ORDER BY (directly or through an alias);
-- * without an outer ORDER BY, window results come out in the first
--   window's PARTITION BY + ORDER BY order (SQLite's sorter);
-- * UNION / INTERSECT / EXCEPT rows come out sorted by every column
--   (multiSelectByMerge); UNION ALL keeps arm order;
-- * the `+YYYY-MM-DD HH:MM:SS` date modifier keeps its seconds.
CREATE TABLE gct(a, b, g);
INSERT INTO gct VALUES(1,'-',1),(2,'+',1),(3,NULL,1),(NULL,'*',1),(4,'/',2),(5,'%',2);
SELECT group_concat(a, b) FROM gct;
SELECT g, group_concat(a, b), string_agg(a, b) FROM gct GROUP BY g;
SELECT group_concat(a, NULL) FROM gct;
SELECT group_concat(b, a) FROM gct;
SELECT group_concat(a, b || '|') FROM gct WHERE g = 1;
SELECT g, group_concat(a, a) FROM gct GROUP BY g HAVING group_concat(a, b) LIKE '%+%';
SELECT group_concat(a, b) OVER (ORDER BY a) FROM gct;
SELECT group_concat(a, b ORDER BY a DESC) FROM gct;
SELECT (SELECT group_concat(a, b) FROM gct AS x WHERE x.g = t.g) FROM gct;
CREATE TABLE w_wo(a, b, g);
INSERT INTO w_wo VALUES(3,'c',2),(1,'a',1),(NULL,'n',1),(2,'b',2),(5,'e',1),(4,'d',2);
/*ordered*/ SELECT a, row_number() OVER (ORDER BY a) FROM w_wo;
/*ordered*/ SELECT a, row_number() OVER (ORDER BY a DESC) FROM w_wo;
/*ordered*/ SELECT a, g, row_number() OVER (PARTITION BY g ORDER BY a) FROM w_wo;
/*ordered*/ SELECT a, g, sum(a) OVER (PARTITION BY g) FROM w_wo;
/*ordered*/ SELECT a, row_number() OVER (ORDER BY a), row_number() OVER (ORDER BY b DESC) FROM w_wo;
/*ordered*/ SELECT a, row_number() OVER (ORDER BY b DESC), row_number() OVER (ORDER BY a) FROM w_wo;
/*ordered*/ SELECT a, count(*) OVER () FROM w_wo;
/*ordered*/ SELECT a, row_number() OVER w FROM w_wo WINDOW w AS (ORDER BY a);
/*ordered*/ SELECT a, rank() OVER (ORDER BY g) FROM w_wo;
/*ordered*/ SELECT a FROM w_wo WHERE a > 1;
CREATE TABLE w_wo2(a, b, g);
INSERT INTO w_wo2 VALUES(3,'c',2),(1,'a',1),(NULL,'n',1),(2,'b',2),(5,'e',1),(4,'d',2);
/*ordered*/ SELECT a, row_number() OVER (ORDER BY a NULLS LAST) FROM w_wo2;
/*ordered*/ SELECT a, row_number() OVER (ORDER BY a DESC NULLS FIRST) FROM w_wo2;
/*ordered*/ SELECT g, sum(a), row_number() OVER (ORDER BY sum(a)) FROM w_wo2 GROUP BY g;
/*ordered*/ SELECT a, row_number() OVER (ORDER BY a) FROM w_wo2 LIMIT 3;
/*ordered*/ SELECT a, row_number() OVER (ORDER BY a) FROM w_wo2 ORDER BY b;
/*ordered*/ SELECT * FROM (SELECT a, row_number() OVER (ORDER BY a DESC) AS r FROM t) WHERE r < 4;
/*ordered*/ SELECT b, lag(b) OVER (PARTITION BY g ORDER BY b) FROM w_wo2;
/*ordered*/ SELECT DISTINCT g, count(*) OVER (PARTITION BY g) FROM w_wo2;
CREATE TABLE w_wob(a);
INSERT INTO w_wob VALUES(2),(1),(3);
/*ordered*/ SELECT a FROM w_wob ORDER BY row_number() OVER (ORDER BY a DESC);
/*ordered*/ SELECT a, row_number() OVER (ORDER BY a) AS r FROM w_wob ORDER BY r DESC;
CREATE TABLE s(region, product, amt);
INSERT INTO s VALUES('n','a',10),('n','b',20),('s','a',5),('s','b',50),('n','a',7),('e','c',1);
/*ordered*/ SELECT region, sum(amt), rank() OVER (ORDER BY sum(amt) DESC) FROM s GROUP BY region;
/*ordered*/ SELECT region, product, sum(amt), row_number() OVER (PARTITION BY region ORDER BY sum(amt) DESC) AS rn FROM s GROUP BY region, product;
/*ordered*/ SELECT region, sum(amt), sum(sum(amt)) OVER () AS total FROM s GROUP BY region;
/*ordered*/ SELECT region, sum(amt) * 100.0 / sum(sum(amt)) OVER () FROM s GROUP BY region;
/*ordered*/ SELECT region, count(*), lag(count(*)) OVER (ORDER BY region) FROM s GROUP BY region;
/*ordered*/ SELECT region, max(amt), dense_rank() OVER w FROM s GROUP BY region WINDOW w AS (ORDER BY max(amt));
/*ordered*/ SELECT region, sum(amt) FROM s GROUP BY region ORDER BY rank() OVER (ORDER BY sum(amt));
/*ordered*/ SELECT count(*), row_number() OVER () FROM s;
/*ordered*/ SELECT region, avg(amt), first_value(region) OVER (ORDER BY avg(amt)) FROM s GROUP BY region HAVING count(*) > 1;
